review.publicAPI:
All public types are Sendable and Hashable; the records are also Codable.
- enum EstimatedOneRepMax { static func epley(load: Double, reps: Int) -> Double; static func bestWorkingSet(_ sets: [SetResult]) -> (set: SetResult, e1rm: Double)? }
- struct ExerciseReviewInput { exercise: ExerciseDefinition; targetID: UUID; dayID: UUID; sets: Int; repMin: Int; repMax: Int; history: [ExerciseHistoryEntry] }
- struct RecoveryContext { hrvDropped, restingHeartRateRose, sleepLow, hasData: Bool; static let unknown }. The init has defaults: init(hrvDropped: = false, restingHeartRateRose: = false, sleepLow: = false, hasData:)
- struct ReviewInput { programID: UUID; programName: String; programDayCount: Int; programStartDate: Date?; exercises: [ExerciseReviewInput]; sessions: [SessionSummary]; weeklySetTarget: ClosedRange<Int>; muscleTargets: [MuscleGroup: Int]? = nil; currentPrescriptions: [ExercisePrescription]; recovery: RecoveryContext = .unknown; mesocycleWeeks: Int = 8; weekStartsOnMonday: Bool = true }
- enum ProgramSuggestionKind: String, Codable, CaseIterable { deload, addSets, removeSets, swapExercise, changeRepRange, reduceDays, switchProgram }
- enum SuggestionStrength: String, Codable { recommended, optional }
- struct ProgramSuggestion: Identifiable, Codable { id: String; kind; rule: String; title: String; reason: String; targetIDs: [UUID]; muscle: MuscleGroup?; proposedSets: Int? (the new absolute set count per target); proposedRepRange: ClosedRange<Int>?; strength; referenceTopic: String }
- struct ReviewReport: Codable { generatedAt: Date; stagnantExerciseIDs: [UUID]; fatigueHigh: Bool; weeklySetsByMuscle: [MuscleGroup: Double]; adherence: Double?; suggestions: [ProgramSuggestion] }
- enum ProgramReviewer { static func review(input: ReviewInput, now: Date, calendar: Calendar) -> ReviewReport }
- struct PersonalRecord: Codable { exerciseID: UUID; e1rm: Double; previousBest: Double?; load: Double; reps: Int }
- enum PersonalRecordDetector { static func newRecords(latestSessionID: UUID, histories: [UUID: [ExerciseHistoryEntry]]) -> [PersonalRecord] }

Suggestion id formats, where W is the ISO week of `now` in the calendar's time zone (e.g. 2026-W39):
- deload:W
- reduceDays:W
- addSets:<muscle>:<targetID>:W and removeSets:<muscle>:<targetID>:W
- changeRepRange:<targetID>:W
- swapExercise:<exerciseID>:W
- switchProgram:<programID>:W

Reference topics:
- deload: rule.D
- addSets and removeSets: topic.volume
- reduceDays: topic.frequency
- changeRepRange, swapExercise and switchProgram: topic.substitution
